	std::function<bool(wxEvtHandler*)> callback;
	if (mo || !error.opt_key.empty()) {
		callback =
			[id = mo ? mo->id() : 0, opt = error.opt_key](wxEvtHandler*) {
			auto& objects = wxGetApp().model().objects;
			auto iter = id.id ? std::find_if(objects.begin(), objects.end(), [id](auto o) { return o->id() == id; }) : objects.end();
			if (iter != objects.end()) {
				wxGetApp().obj_list()->select_items({ {*iter, nullptr} });
                wxGetApp().obj_list()->update_selections_on_canvas();
            }
			if (!opt.empty()) {
				if (iter != objects.end())
					wxGetApp().params_panel()->switch_to_object();
				wxGetApp().sidebar().jump_to_option(opt, Preset::TYPE_PRINT, L"");
			}
			else {
				wxGetApp().mainframe->select_tab(MainFrame::tp3DEditor);
			}
			return false;
		};
	}
    auto link = (mo || !error.opt_key.empty()) ? _u8L("Jump to") : "";
    if (mo) link += std::string(" [") + mo->name + "]";
    */
    auto mi = dynamic_cast<ModelInstance const *>(error.object);
	std::function<bool(wxEvtHandler*)> callback;
	if (mo || mi || !error.opt_key.empty()) {
		callback =
			[id = mo ? mo->id() : (mi ? mi->id() : 0),
             parent_id = mi ? mi->get_object()->id() : 0,
             is_inst = (mi != nullptr),
             opt = error.opt_key](wxEvtHandler*) {
			auto& objects = wxGetApp().model().objects;

            if (is_inst) {
                 bool selected = false;
                 auto iter = std::find_if(objects.begin(), objects.end(), [parent_id](auto o) { return o->id() == parent_id; });
                 if (iter != objects.end()) {
                      ModelObject* obj = *iter;
                      int inst_idx = -1;
                      for(size_t i=0; i<obj->instances.size(); ++i) {
                          if (obj->instances[i]->id() == id) {
                              inst_idx = i;
                              break;
                          }
                      }
                      if (inst_idx != -1) {
                         auto* model = wxGetApp().obj_list()->GetModel();
                         wxDataViewItem item;
                         wxDataViewItem objItem = model->GetObjectItem(obj);
                         if (objItem.IsOk()) {
                             int vm_obj_idx = model->GetIdByItem(objItem);
                             if (vm_obj_idx != -1) {
                                 item = model->GetItemByInstanceId(vm_obj_idx, inst_idx);
                             }
                         }
                         if (item.IsOk()) {
                             wxDataViewItemArray sel_items;
                             sel_items.Add(item);
                             wxGetApp().obj_list()->select_items(sel_items);
                             selected = true;
                         }
                      }

                      if (!selected) {
                           wxGetApp().obj_list()->select_items({ {obj, nullptr} });
                      }
                 }
            } else {
			    auto iter = id.id ? std::find_if(objects.begin(), objects.end(), [id](auto o) { return o->id() == id; }) : objects.end();
			    if (iter != objects.end())
				    wxGetApp().obj_list()->select_items({ {*iter, nullptr} });
            }

			if (!opt.empty()) {
				const Preset::Type opt_type = resolve_validation_option_type(opt);

				if (opt_type == Preset::TYPE_PRINT && ((!is_inst && id.id) || (is_inst && parent_id.id))) // if object found and it's a print preset option, switch to object first
					wxGetApp().params_panel()->switch_to_object();

				wxGetApp().sidebar().jump_to_option(opt, opt_type, L"");
			}
			else {
				wxGetApp().mainframe->select_tab(MainFrame::tp3DEditor);
			}
			return false;
		};
	}
    auto link = (mo || mi || !error.opt_key.empty()) ? _u8L("Jump to") : "";
    if (mo) link += std::string(" [") + mo->name + "]";
    if (mi) link += std::string(" [") + mi->get_object()->name + "]";
    if (!error.opt_key.empty()) link += std::string(" (") + error.opt_key + ")";
    push_notification_data({NotificationType::ValidateError, NotificationLevel::ErrorNotificationLevel, 0, _u8L("Error:") + "\n" + error.string, link, callback}, 0);
	set_slicing_progress_hidden();
}

void NotificationManager::push_slicing_error_notification(const std::string &text, std::vector<ModelObject const *> objs)
{
    std::vector<ObjectID> ids;
    for (auto optr : objs) {
        if (optr)
            ids.push_back(optr->id());
    }
	std::function<bool(wxEvtHandler*)> callback;
	if (!objs.empty()) {
		callback = [ids](wxEvtHandler*) {
			auto& objects = wxGetApp().model().objects;
			std::vector<ObjectVolumeID> ovs;
			for (auto id : ids) {
				auto iter = std::find_if(objects.begin(), objects.end(), [id](auto o) { return o->id() == id; });
				if (iter != objects.end()) { ovs.push_back({ *iter, nullptr }); }
			}
			if (!ovs.empty()) {
				wxGetApp().mainframe->select_tab(MainFrame::tp3DEditor);
				wxGetApp().obj_list()->select_items(ovs);
			}
			return false;
		};
	}
    auto link     = callback ? _u8L("Jump to") : "";
    if (!objs.empty()) {
        link += " [";
        for (auto obj : objs) {
            if (obj)
                link += obj->name + ", ";
        }
        if (!objs.empty()) {
            link.pop_back();
            link.pop_back();
        }
        link += "] ";
    }
    set_all_slicing_errors_gray(false);
	push_notification_data({ NotificationType::SlicingError, NotificationLevel::ErrorNotificationLevel, 0,  _u8L("Error:") + "\n" + text, link, callback }, 0);
	set_slicing_progress_hidden();
}
void NotificationManager::push_slicing_warning_notification(const std::string& text, bool gray, ModelObject const * obj, ObjectID oid, int warning_step, int warning_msg_id, NotificationLevel level/* = NotificationLevel::WarningNotificationLevel*/)
{
	std::function<bool(wxEvtHandler*)> callback;
	if (obj) {
		callback = [id = obj->id()](wxEvtHandler*) {
			auto& objects = wxGetApp().model().objects;
			auto iter = std::find_if(objects.begin(), objects.end(), [id](auto o) { return o->id() == id; });
			if (iter != objects.end()) {
				wxGetApp().mainframe->select_tab(MainFrame::tp3DEditor);
				wxGetApp().obj_list()->select_items({ {*iter, nullptr} });
			}
			return false;
		};
	}
    auto link = callback ? _u8L("Jump to") : "";
    if (obj) link += std::string(" [") + obj->name + "]";
	NotificationData data { NotificationType::SlicingWarning, level, 0,  _u8L("Warning:") + "\n" + text, link, callback };

	data.sub_msg_id = warning_msg_id;
	data.ori_text = text;

	auto notification = std::make_unique<NotificationManager::ObjectIDNotification>(data, m_id_provider, m_evt_handler);
	notification->object_id = oid;
	notification->warning_step = warning_step;
	if (push_notification_data(std::move(notification), 0)) {
		m_pop_notifications.back()->set_gray(gray);
	}
}
